input.command:
cat > exegenius/tasks/0002-background.answer.json <<'EOF'
{
  "summary": "The reader is an undergraduate computer scientist: fluent with big-O and basic algorithm analysis (recurrences, divide and conquer, sorting and merging, schoolbook multiplication), discrete mathematics (sets, binomial coefficients, permutations, modular arithmetic, primes, gcd), and introductory linear algebra and complex numbers including roots of unity and polynomial arithmetic. They have seen single-tape and multitape Turing machines and tapes as a cost model, but not the discrete Fourier transform, FFT, fast integer multiplication, abstract algebra beyond residues, number-theoretic estimates such as the prime number theorem, or any research-level multiplication technique.",
  "known": [
    {
      "name": "Binary representation of integers",
      "aliases": ["binary expansion", "bit string", "bits", "radix representation", "base-b digits", "val(x)"],
      "gloss": "A nonnegative integer is written as a string of bits, or digits in a radix b, with value the sum of digit times power of the radix."
    },
    {
      "name": "Modular arithmetic",
      "aliases": ["congruence", "residues mod m", "mod", "residue ring Z/mZ", "centered residue", "modular inverse"],
      "gloss": "Integers are compared and combined modulo a positive integer m, with addition, subtraction and multiplication well defined on residue classes and inverses existing for residues coprime to m."
    },
    {
      "name": "Primes, divisibility, coprimality and gcd",
      "aliases": ["prime numbers", "relatively prime", "coprime", "pairwise coprime", "greatest common divisor", "Euclidean algorithm", "extended Euclidean algorithm", "trial division"],
      "gloss": "A prime has no divisors besides 1 and itself, two integers are coprime when their gcd is 1, and the (extended) Euclidean algorithm computes gcds and modular inverses; primality can be tested by trial division."
    },
    {
      "name": "Logarithms, floors and ceilings",
      "aliases": ["log base 2", "lg", "binary logarithm", "floor", "ceiling", "natural logarithm", "powers of two"],
      "gloss": "Basic manipulation of logarithms and exponentials, and of floor and ceiling rounding, as used in sizes such as the number of bits of n."
    },
    {
      "name": "Divide and conquer and recurrences",
      "aliases": ["recursion", "recurrence relation", "master theorem", "geometric series", "unrolling a recurrence", "induction"],
      "gloss": "Running times of recursive algorithms are bounded by solving recurrences such as T(n)=aT(n/b)+f(n), including summing geometric series, and results are proved by induction."
    },
    {
      "name": "Sorting, merging and radix sort",
      "aliases": ["merge sort", "stable sort", "radix sorting", "counting sort", "merge", "sorting by keys"],
      "gloss": "Standard sorting methods: merging two sorted lists in linear time, merge sort in n log n, and stable radix sort by digits."
    },
    {
      "name": "Schoolbook multiplication and carries",
      "aliases": ["long multiplication", "grade-school multiplication", "carry propagation", "quadratic multiplication", "Karatsuba"],
      "gloss": "Multiplying two n-digit numbers digit by digit with carries takes O(n^2) time; Karatsuba's divide-and-conquer lowers this to n^1.585."
    },
    {
      "name": "Permutations",
      "aliases": ["permutation of coordinates", "bijection", "reordering", "partial permutation", "transposition", "inverse permutation"],
      "gloss": "A permutation is a bijective reordering of a finite list of positions, composed and inverted as functions."
    },
    {
      "name": "Sets, subsets and binomial coefficients",
      "aliases": ["n choose k", "binomial coefficient", "counting subsets", "cardinality", "intersection of sets", "indicator vector", "ground set"],
      "gloss": "Finite sets, their intersections and cardinalities, and the count C(h,k) of k-element subsets of an h-element set."
    },
    {
      "name": "XOR and mod 2 arithmetic",
      "aliases": ["bitwise XOR", "exclusive or", "GF(2) addition", "addition mod 2", "bitwise operations", "F2 arithmetic"],
      "gloss": "Bits are added modulo 2, which is the XOR operation, and bit vectors are added coordinatewise."
    },
    {
      "name": "Hamming weight",
      "aliases": ["wt(x)", "population count", "popcount", "number of one bits"],
      "gloss": "The Hamming weight of a bit vector is the number of its coordinates equal to 1."
    },
    {
      "name": "Matrices and matrix-vector products",
      "aliases": ["matrix multiplication", "identity matrix", "invertible matrix", "transpose", "diagonal matrix", "lower-triangular matrix", "Gaussian elimination", "block matrix"],
      "gloss": "Rectangular arrays acting on vectors by multiplication, composed by matrix product, with identity, inverse, diagonal and triangular matrices and elimination by row operations."
    },
    {
      "name": "Vector norms and the triangle inequality",
      "aliases": ["maximum norm", "sup norm", "absolute value of a complex number", "modulus", "triangle inequality", "operator norm"],
      "gloss": "The size of a vector is measured by a norm such as the maximum absolute value of its entries, which satisfies the triangle inequality and scales with scalars."
    },
    {
      "name": "Lexicographic order and mixed-radix indexing",
      "aliases": ["lexicographic order", "dictionary order", "row-major order", "multi-index", "mixed radix", "Cartesian product", "most significant coordinate"],
      "gloss": "Tuples are ordered by comparing coordinates from the most significant first, so a multi-index (a1,...,ad) with ranges corresponds to a single integer position."
    },
    {
      "name": "Two's complement and signed integers",
      "aliases": ["signed integer encoding", "sign-magnitude", "sign extension"],
      "gloss": "Signed integers are stored in fixed-width binary words in which the top bit carries negative weight."
    },
    {
      "name": "Dyadic and rational numbers",
      "aliases": ["dyadic rational", "rational numbers", "fractions with power-of-two denominator", "exact arithmetic"],
      "gloss": "Rational numbers are quotients of integers, and dyadic rationals are those whose denominator is a power of two, i.e. finite binary fractions."
    },
    {
      "name": "Euler's formula and complex conjugation",
      "aliases": ["e^{i theta}", "complex conjugate", "unit circle", "real and imaginary parts", "Gaussian integers"],
      "gloss": "e^{i theta}=cos theta + i sin theta, the complex conjugate negates the imaginary part, and complex numbers with integer real and imaginary parts are Gaussian integers."
    },
    {
      "name": "Tape-based subroutines and stacks",
      "aliases": ["subroutine call", "call stack", "program counter", "work tape", "scanning a tape", "tape copying and reversal"],
      "gloss": "Basic Turing machine programming: scanning, copying, reversing and rewriting tape contents in linear passes, and simulating subroutine calls with a stack."
    },
    {
      "name": "Constant factors versus asymptotic dominance",
      "aliases": ["little-o", "Theta notation", "Omega notation", "o(1)", "for sufficiently large n", "polylogarithmic", "dominant term"],
      "gloss": "Asymptotic comparisons using Theta, Omega and little-o, where polynomial growth in a quantity beats polylogarithmic factors in it."
    }
  ]
}
EOF
exegenius submit 0002-background

